void PrintBusinessLines(string[] lines,string title){int index=0;List<string> wrapped=null;using(var doc=new PrintDocument()){doc.DocumentName=title;doc.BeginPrint+=(o,e)=>{index=0;wrapped=null;};doc.PrintPage+=(o,e)=>{using(var font=new Font("���� ����",10)){if(wrapped==null){wrapped=new List<string>();foreach(string raw in lines)foreach(string paragraph in (raw??"").Split('\n')){string rest=paragraph;if(rest.Length==0)wrapped.Add("");while(rest.Length>0){int n=rest.Length;while(n>1&&e.Graphics.MeasureString(rest.Substring(0,n),font).Width>e.MarginBounds.Width)n--;wrapped.Add(rest.Substring(0,n));rest=rest.Substring(n);}}}float y=e.MarginBounds.Top,lineHeight=font.GetHeight(e.Graphics)+7;while(index<wrapped.Count){if(y+lineHeight>e.MarginBounds.Bottom){e.HasMorePages=true;return;}e.Graphics.DrawString(wrapped[index++],font,Brushes.Black,e.MarginBounds.Left,y);y+=lineHeight;}}e.HasMorePages=false;};using(var preview=new PrintPreviewDialog{Document=doc,Width=1000,Height=800})preview.ShowDialog(this);}}

